export function reconcileSources(observed:readonly string[],projected:readonly string[],remainder:readonly string[]):void {
 const unique=(xs:readonly string[])=>new Set(xs);const o=unique(observed),p=unique(projected),r=unique(remainder);
 check(o.size===observed.length&&p.size===projected.length&&r.size===remainder.length,'duplicate_source_accounting');
 check([...p].every(x=>o.has(x)&&!r.has(x))&&[...r].every(x=>o.has(x))&&o.size===p.size+r.size,'source_conservation_required');
}
function projectionObjects(w:WindowResult,type:EducationType){return w.items.filter((x):x is Extract<TypedItem,{kind:'OBJECT'}>=>x.kind==='OBJECT'&&x.record.identity.objectType===type).map(x=>x.record);}
