async function inventory(db:SQL):Promise<Census> {
 return db.begin(async tx=>{
  await tx`SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY`;
  const rows=await tx`SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='academy' ORDER BY tablename`;
  const names=rows.map((x:{tablename:unknown})=>String(x.tablename));check(names.length>=minimumBusinessTables.length&&minimumBusinessTables.every(x=>names.includes(x)),'complete_schema_inventory_required');
  const tables:Census['tables']={};
  for(const name of names){
   check(/^[a-z][a-z0-9_]*$/.test(name),'catalog_identifier_required');
   // Identifier comes only from actual pg_catalog, never caller/table input.
   const actual=await tx.unsafe('SELECT row_to_json(t) AS value FROM academy."'+name+'" t');
   const hashes=actual.map((row:{value:unknown})=>sha256(canonicalJson(row.value))).sort();
   tables[name]={rows:hashes.length,sha256:sha256(JSON.stringify(hashes))};
  }
  return {inventoryDigest:sha256(JSON.stringify(names)),tables};
 }) as Promise<Census>;
}
function assertBusinessUnchanged(before:Census,after:Census):void {
 check(before.inventoryDigest===after.inventoryDigest,'schema_changed_in_read_window');
 for(const [table,value] of Object.entries(before.tables))if(!auditTables.has(table))check(JSON.stringify(value)===JSON.stringify(after.tables[table]),'business_changed_in_read_window');
}
