 return rows.map((r:{request_id:string;request:unknown;status:string;snapshot_digest:string|null;refusal_code:string|null})=>({requestId:r.request_id,bindingSha256:sha256(canonicalJson(r.request)),status:r.status,snapshotDigest:r.snapshot_digest,refusalCode:r.refusal_code}));
