async function qualificationCases(i:FixedRunnerInvocation,memory:NativeMemory,db:SQL,store:PostgresAcademyStore,witnesses:Record<string,unknown>[]){
 const cases=[...memoryGet(memory,'native.qualificationCases') as QualificationCase[]].sort((a,b)=>Number(a.mode==='EXPIRY')-Number(b.mode==='EXPIRY'));
 check(Array.isArray(cases)&&['DUPLICATE','DISTINCT','BARRIER','ENCODING_FAILURE','ACK_SUPPRESSION','DRIVER_ACK_LOSS','EXPIRY','TRANSPORT_SUPPRESSION'].every(mode=>cases.some(q=>q.mode===mode)),'root_sealed_finite_cases_required');
 const helperDirectory=String(memoryGet(memory,'native.helperMetadataDirectory'));
 check(isDirectPhaseMetadataDirectory(helperDirectory),'exact_helper_metadata_directory');
 const caseIds=(memory['measurement.caseRequestIds']??=[]) as string[];
 for(const q of cases){
  if(q.mode==='EXPIRY'){
   // Consume the already Root-sealed one-shot arm only at the real native
   // login immediately preceding this case, after all longer baseline work.
   const identity=memoryGet(memory,'native.identityA') as {username:string};
   const login=await nativePost(i,'/api/login',{username:identity.username,password:memoryGet(memory,'memory.generatedPassword.A')},null);
   check(login.status===200&&!!login.cookie,'genuine_selected_short_login_required');
   memory['memory.cookie.A']=login.cookie;
  }
  const intent=intentFor(i,memory),snapshot=await acquire(i,memory,intent),request=makeRequest(i,intent,snapshot,{kind:'EXACT_OBJECT',objectRef:memoryGet(memory,'refs.s1') as ObjectRef});
  request.requestId=q.requestId;request.functionRequest.requestId=q.requestId;caseIds.push(q.requestId);if(q.peerRequestId)caseIds.push(q.peerRequestId);
  let release!:()=>void,ready!:()=>void;let blocker=0;
  const hold=new Promise<void>(r=>{release=r;}),locked=new Promise<void>(r=>{ready=r;});
  const barrier=q.barrier?db.begin(async tx=>{
   blocker=Number((await tx`SELECT pg_backend_pid() AS pid`)[0]!.pid);
   await tx`SELECT pg_advisory_xact_lock(hashtextextended(${JSON.stringify(['p4-qualification-barrier',i.config.base.ownerId,q.id])},0))`;ready();await hold;
  }):null;
  if(barrier)await locked;
  if(q.mode==='EXPIRY'){const token=String(memoryGet(memory,'memory.cookie.A')).split('=')[1]!,claims=JSON.parse(Buffer.from(token.split('.')[0]!,'base64url').toString('utf8')) as {expiresAt:number};check(claims.expiresAt*1000>Date.now()&&claims.expiresAt*1000-Date.now()<=30000,'root_must_schedule_genuine_near_expiry_session');}
  const response=nativePost(i,'/api/typed-read',request,String(memoryGet(memory,'memory.cookie.A')));
  let waitWitness:unknown=null;
  try{
   if(barrier){
    const deadline=Date.now()+300000;let waiters:number[]=[];
    while(Date.now()<deadline){const rows=await db`SELECT pid FROM pg_stat_activity WHERE datname=current_database() AND ${blocker}=ANY(pg_blocking_pids(pid))`;waiters=rows.map((r:{pid:number})=>Number(r.pid));if(waiters.length)break;await new Promise<void>(r=>setTimeout(r,1));}
    check(waiters.length>0,'actual_qualification_barrier_wait_required');waitWitness={blocker,blocked:waiters};
    if(q.mode==='DUPLICATE'){
     const rows=await db`SELECT a.pid,pg_blocking_pids(a.pid) AS blockers FROM pg_stat_activity a WHERE a.datname=current_database() AND cardinality(pg_blocking_pids(a.pid))>0`;
     check(rows.some((r:{pid:number;blockers:number[]})=>Number(r.pid)!==waiters[0]&&r.blockers.some(pid=>pid!==blocker)),'actual_same_read_key_wait_required');
    }
    if(q.mode==='BARRIER'){
     // This contender uses the genuine B0 identity and the actual private
     // auth lock. The retained SQL barrier keeps the output lease live.
     const {TeacherAuthStore}=await import('../src/academy/teacherAuthStore');
     const auth=new TeacherAuthStore(i.config.base.authFile),genuineB=memoryGet(memory,'native.identityB') as Parameters<typeof auth.substituteCoordinatedIdentityOnly>[1];
     let busy=false;try{auth.substituteCoordinatedIdentityOnly({expectedAuthSha256:sha256(readFileSync(i.config.base.authFile)),assertOccurrence:i.assertCurrent},genuineB);}catch(error){busy=error instanceof Error&&error.message==='private_auth_lock_required';}
     check(busy,'actual_auth_lease_writer_exclusion_required');
    }
   }
  }finally{release?.();if(barrier)await barrier;}
  const result=await response;
  const expected=q.mode==='ACK_SUPPRESSION'||q.mode==='DRIVER_ACK_LOSS'||q.mode==='TRANSPORT_SUPPRESSION'?503:q.mode==='EXPIRY'?401:q.mode==='ENCODING_FAILURE'?409:200;
  check(result.status===expected,'finite_native_case_disposition');
  if(expected!==200)check(!Object.hasOwn(result.body,'items')&&!Object.hasOwn(result.body,'nextCursor'),'fault_buffer_discard_required');
  const lookup=await lookupRead(i,memory,db,store,q.requestId,q.mode!=='EXPIRY');
  check(lookup.status===(q.mode==='ENCODING_FAILURE'?'REFUSED':'COMPLETED'),'native_fault_terminal_truth');
  const paths=readdirSync(helperDirectory).filter(name=>name.startsWith('q-'+q.id+'-')&&name.endsWith('.json')).sort();
  const evidence=paths.map(name=>{const raw=readFileSync(join(helperDirectory,name));const value=JSON.parse(raw.toString('utf8')) as Record<string,unknown>;check(value.sourceSetSha256===i.config.base.sourceSet.sha256&&value.runId===i.config.base.runId&&value.ownerId===i.config.base.ownerId&&value.caseId===q.id,'exact_native_case_receipt');return {name,sha256:sha256(raw),stage:value.stage,backendPid:value.backendPid??null};});
  check(evidence.length>0,'actual_native_case_receipts_required');
  if(q.mode==='DRIVER_ACK_LOSS'){
   const receipts=paths.map(name=>JSON.parse(readFileSync(join(helperDirectory,name),'utf8')) as Record<string,unknown>);
   const lost=receipts.filter(r=>r.stage==='driver-ack-loss');
   check(lost.length===1&&lost[0]!.driverAckForwarded===false&&lost[0]!.driverCommitKnown===false&&Number.isSafeInteger(lost[0]!.backendPid)&&Number.isSafeInteger(lost[0]!.connectionId),'actual_driver_commit_ack_loss_required');
   check(!receipts.some(r=>r.stage==='known-commit'),'target_driver_commit_must_remain_unknown');
   check((result.body.error as {code?:unknown}|undefined)?.code==='READ_UNRESOLVED'&&lookup.status==='COMPLETED','original_unknown_and_independent_terminal_required');
  }

  if(q.peerRequestId){const peer=await lookupRead(i,memory,db,store,q.peerRequestId);check(peer.status==='COMPLETED','distinct_admissions_both_complete');}
  const modeOracle:Record<string,string>={DUPLICATE:'V-OWNER-GATE-DUPLICATE-SAME-ADMISSION',DISTINCT:'V-OWNER-GATE-DISTINCT-ADMISSIONS',ACK_SUPPRESSION:'V-COMMIT-UNKNOWN',DRIVER_ACK_LOSS:'V-COMMIT-UNKNOWN',BARRIER:'V-POST-COMMIT-EMISSION',ENCODING_FAILURE:'V-PRE-EGRESS-FAILURE',TRANSPORT_SUPPRESSION:'V-PRE-EGRESS-FAILURE'};
  witnesses.push({...(modeOracle[q.mode]?{oracle:modeOracle[q.mode]}:{}),kind:'FINITE_CASE',caseId:q.id,mode:q.mode,requestId:q.requestId,status:result.status,responseSha256:result.digest,lookup,waitWitness,evidence,driverCommitUncertainty:q.mode==='DRIVER_ACK_LOSS'?'ACK_WITHHELD_DB_RECONCILED_NO_KERNEL_CLAIM':q.mode==='ACK_SUPPRESSION'?'UNQUALIFIED_OWNER_ACK_SUPPRESSION_ONLY':null});
 }
}

