 for(const size of [0,101]){const request=structuredClone(base);request.requestId=crypto.randomUUID();request.pageSize=size;if('pageSize' in request.functionRequest)request.functionRequest.pageSize=size;await refuseRead(i,memory,request,cookie,[400],witnesses,'page-size-'+size);}
