 check(attempt1.entityId!==attempt2.entityId&&attempt1.revisionId===attempt2.payload.previousAttemptRevisionId&&attempt1.payload.assignmentRevisionId===attempt2.payload.assignmentRevisionId,'actual_attempt_family_lineage');
