 check(approvals.some((r:{body:{payload:{state:string}}})=>r.body.payload.state==='CONSUMED'),'actual_consumed_approval_receipt');witnesses.push({oracle:'V-DRAFT-ASSESSMENT',approvedRevision:sha256(draft.revision),consumedProof:true});
